import argparse

def sieve_of_eratosthenes(upper_bound):
    sieve = [True] * (upper_bound + 1)
    sieve[0], sieve[1] = False, False
    p = 2
    while p * p <= upper_bound:
        if sieve[p]:
            for i in range(p * p, upper_bound + 1, p):
                sieve[i] = False
        p += 1
    return [num for num, is_prime in enumerate(sieve) if is_prime]

def find_twin_primes(primes):
    twins = []
    for i in range(len(primes) - 1):
        if primes[i+1] - primes[i] == 2:
            twins.append((primes[i], primes[i+1]))
    return twins

def main():
    parser = argparse.ArgumentParser(description='Sieve of Eratosthenes with twin prime option')
    parser.add_argument('upper_bound', type=int, help='Upper bound for primes')
    parser.add_argument('--twin', action='store_true', help='Find twin primes')
    args = parser.parse_args()

    primes = sieve_of_eratosthenes(args.upper_bound)
    if args.twin:
        twins = find_twin_primes(primes)
        print(f'Twin primes: {twins}')
        print(f'Count of twin primes pairs: {len(twins)}')
    else:
        print(f'Primes up to {args.upper_bound}: {primes}')
        print(f'Count of primes: {len(primes)}')

if __name__ == '__main__':
    main()
